const incoming = $input.first()?.json ?? {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const required = ['brief', 'platforms'];
const missing = required.filter((key) => body[key] === undefined || body[key] === null || body[key] === '');
const platforms = Array.isArray(body.platforms) ? body.platforms : [body.platforms];
const allowed = new Set(['instagram', 'facebook', 'tiktok', 'youtube', 'x', 'linkedin']);
const invalidPlatforms = platforms.filter((p) => typeof p !== 'string' || !allowed.has(p.toLowerCase()));
const requestId = typeof body.request_id === 'string' && body.request_id.trim() ? body.request_id.trim() : `apex_${Date.now()}`;
const brief = typeof body.brief === 'string' ? body.brief : '';
const errors = [...missing.map((k) => `Missing required field: ${k}`), ...(brief.trim().length < 10 ? ['brief must contain at least 10 characters'] : []), ...(brief.length > 5000 ? ['brief must be 5000 characters or fewer'] : []), ...(invalidPlatforms.length ? [`Unsupported platforms: ${invalidPlatforms.join(', ')}`] : [])];
const valid = errors.length === 0 && platforms.length > 0;
return [{ json: { httpStatus: valid ? 200 : 400, response: valid ? { ok: true, request_id: requestId, stage: 'intake_validated', mode: 'foundation_only', message: 'Request format validated. AI generation and Supabase persistence are not connected in this starter workflow.', received: { platforms: platforms.map((p) => p.toLowerCase()), brief_length: brief.length } } : { ok: false, request_id: requestId, error: 'INVALID_CONTENT_REQUEST', details: errors } } }];
